<div class="page-head"><div><h1><?= te('Employment paperwork · I-9 and W-4') ?></h1><p class="sub"><?= te('Track completed official forms and the employer\'s verification. This workflow stores evidence and review records; it does not replace the official forms or an electronic I-9 provider.') ?></p></div></div><div class="card"><a href="https://www.uscis.gov/i-9" target="_blank" rel="noopener"><?= te('Official I-9 form and instructions') ?></a> · <a href="https://www.irs.gov/forms-pubs/about-form-w-4" target="_blank" rel="noopener"><?= te('Official W-4 form') ?></a> · <a href="/proofs"><?= te('Upload completed form evidence') ?></a></div>
<?php if(!$isWorker): ?><form class="card row" method="get"><select name="candidate_id"><?php foreach($candidates as $c): ?><option value="<?= (int)$c['id'] ?>"><?= e($c['full_name']) ?></option><?php endforeach; ?></select><button class="btn"><?= te('Open employment record') ?></button></form><?php endif; ?>
<?php if($case): ?><div class="card"><h2><?= e($case['full_name']) ?></h2><?php $emWord = ['pending' => t('Waiting for the form'), 'employee_submitted' => t('Submitted, waiting for the employer'), 'employer_completed' => t('Completed by the employer'), 'submitted' => t('Submitted, waiting for review'), 'reviewed' => t('Reviewed')]; $emDay = static fn($v) => $v ? d((string) $v) : '—'; ?><p>I-9: <b><?= e($emWord[$case['i9_status']] ?? $case['i9_status']) ?></b> · W-4: <b><?= e($emWord[$case['w4_status']] ?? $case['w4_status']) ?></b></p><p><?= te('First day') ?>: <?= e($emDay($case['first_day'])) ?> · <?= te('Review due') ?>: <?= e($emDay($case['review_due_on'])) ?> · <?= te('Verifier') ?>: <?= e($case['verifier_name'] ?: '—') ?></p></div>
<div class="card" id="portal-forms"><h2><?= te('Filled in the portal') ?></h2><?php $pfWord=['submitted'=>t('Waiting to be checked'),'accepted'=>t('Accepted'),'returned'=>t('Sent back'),'replaced'=>t('Replaced by a newer one')]; foreach(['w4'=>'W-4','i9'=>'I-9 Section 1'] as $k=>$label): $pf=$portalForms[$k]??null; ?><p data-portal-form="<?= e($k) ?>"><strong><?= e($label) ?></strong>: <?php if($pf): ?><?= te('signed :date', ['date'=>d(substr((string)$pf['signed_at'],0,10))]) ?> · <?= e($pfWord[$pf['status']]??$pf['status']) ?> · <a href="/tax-forms?id=<?= (int)$pf['id'] ?>"><?= $isWorker?te('See it'):te('Open it') ?></a><?php else: ?><?= te('not filled in yet') ?><?php endif; ?><?php if($isWorker&&(!$pf||$pf['status']==='returned')): ?> · <a href="/tax-forms?fill=<?= e($k) ?>"><?= te('Fill it in here') ?></a><?php endif; ?></p><?php endforeach; ?></div>
<?php if($isWorker): ?><p class="small muted"><?= te('Or, if you filled the official form on paper and uploaded it:') ?></p><div class="grid g2"><?php foreach(['section1'=>'I-9 Section 1','w4'=>'W-4'] as $action=>$label): ?><form class="card" method="post"><?= csrf_field() ?><input type="hidden" name="do" value="<?= e($action) ?>"><h2><?= e($label) ?></h2><label><?= te('Uploaded completed form') ?></label><select name="document_id"><?php foreach($documents as $d): ?><option value="<?= (int)$d['id'] ?>"><?= e($d['document_type'].' · '.$d['status']) ?></option><?php endforeach; ?></select><label><input class="w-auto" type="checkbox" name="attest" required> <?= te('I completed and signed the official form identified above.') ?></label><button class="btn"><?= te('Submit form for review') ?></button></form><?php endforeach; ?></div>
<?php else: ?><form class="card" method="post"><?= csrf_field() ?><input type="hidden" name="do" value="employer"><input type="hidden" name="candidate_id" value="<?= $cid ?>"><h2><?= te('Record completed employer verification') ?></h2><label><?= te('Completed employer-signed I-9 evidence') ?></label><select name="document_id"><?php foreach($documents as $d): ?><option value="<?= (int)$d['id'] ?>"><?= e($d['document_type'].' · '.$d['status']) ?></option><?php endforeach; ?></select><label><?= te('Authorized verifier\'s name') ?></label><input name="verifier_name" required maxlength="190"><label><?= te('Verification performed by') ?></label><select name="verification_method"><option value="in_person"><?= te('Employer in person') ?></option><option value="authorized_representative"><?= te('Authorized representative in person') ?></option></select><div class="row"><div><label><?= te('First day of employment') ?></label><input type="date" name="first_day" required></div><div><label><?= te('Employer review deadline · set from applicable business calendar') ?></label><input type="date" name="review_due_on" required></div></div><label><input class="w-auto" type="checkbox" name="attest" required><?= te('The authorized verifier examined the required original documents and completed and signed the employer section of the official I-9.') ?></label><button class="btn"><?= te('Record employer completion') ?></button></form><form class="card" method="post"><?= csrf_field() ?><input type="hidden" name="do" value="review_w4"><input type="hidden" name="candidate_id" value="<?= $cid ?>"><h2><?= te('W-4 review') ?></h2><p><?= te('Review the submitted form and forward it through the approved payroll process.') ?></p><button class="btn"><?= te('Mark W-4 reviewed') ?></button></form><?php endif; endif; ?>
<?php if (! $isWorker && $case): ?>
<div class="card" id="signing"><h2><?= te('W-4 signed in person') ?></h2>
  <?php if (! empty($case['w4_in_person_at'])): ?><p data-w4-in-person="1"><span class="tag green"><?= te('Signed in person') ?></span> <?= te(':date, witnessed by :name', ['date' => d(substr((string) $case['w4_in_person_at'], 0, 10)), 'name' => $witness]) ?></p><?php endif; ?>
  <?php if ($signing): ?>
    <p><?= te('Show this to :name. They enter it in their portal, under Employment, with their W-4. It works once, until :time.', ['name' => $case['full_name'], 'time' => date('g:i a', strtotime($signing['expires']))]) ?></p>
    <p class="big-figure mono" id="signing-code"><?= e(substr($signing['code'], 0, 4) . ' ' . substr($signing['code'], 4)) ?></p>
    <div class="signing-qr" data-code="<?= e($signing['code']) ?>"></div>
    <script src="/assets/qrcode.min.js"></script>
    <script>document.querySelectorAll('.signing-qr').forEach(el=>new QRCode(el,{text:location.origin+'/employment?sign='+el.dataset.code,width:192,height:192,correctLevel:QRCode.CorrectLevel.M}));</script>
  <?php else: ?>
    <p class="small muted"><?= te('With the worker in front of you: scan their completed W-4 under Documents, then make a one-time code. They sign by entering it, or scanning its QR code, from their own phone.') ?></p>
    <form method="post"><?= csrf_field() ?><input type="hidden" name="do" value="signing_code"><input type="hidden" name="candidate_id" value="<?= $cid ?>"><button class="btn"><?= te('Make a signing code') ?></button></form>
  <?php endif; ?>
</div>
<?php endif; ?>
<?php if ($isWorker && $case && ($case['w4_status'] ?? '') !== 'reviewed'): ?>
<form class="card" id="sign" method="post" action="/employment"><?= csrf_field() ?><input type="hidden" name="do" value="w4_in_person">
  <h2><?= te('Sign your W-4 with the coordinator') ?></h2>
  <p class="small muted"><?= te('Enter the code the coordinator shows you. It proves you signed in person.') ?></p>
  <div class="row">
    <div><label for="sign-code"><?= te('Code') ?></label><input id="sign-code" name="code" inputmode="numeric" maxlength="9" required value="<?= e($signFromLink) ?>" autocomplete="one-time-code"></div>
    <div class="f2"><label for="sign-doc"><?= te('Your scanned W-4') ?></label><select id="sign-doc" name="document_id"><?php foreach ($documents as $d): ?><option value="<?= (int) $d['id'] ?>"><?= e($d['document_type']) ?></option><?php endforeach; ?></select></div>
  </div>
  <label class="tick"><input type="checkbox" name="attest" value="1" required> <?= te('I completed and signed this W-4 myself.') ?></label>
  <button class="btn mt-s"><?= te('Sign my W-4') ?></button>
</form>
<?php endif; ?>
